import { createApp } from "./app";
import { InMemoryOrderRepository } from "./in-memory-order-repository";
import { InMemoryProductRepository } from "./in-memory-product-repository";
import { createOrderController } from "./order-module";
import { seedCatalogue } from "./seed-catalogue";
import { createStockController } from "./stock-module";

const orders = new InMemoryOrderRepository();
const products = new InMemoryProductRepository(seedCatalogue());

const app = createApp(createOrderController(orders, products), createStockController(products));

const port = Number(process.env.PORT ?? 3000);
app.listen(port, () => {
  console.log(`Order fulfilment API listening on port ${port}`);
});

